COPILOT_PROMPTS_DIR = "builder.copilot.prompts"
COPILOT_PROMPTS_FILE = "copilot_system_prompt.jinja2"
COPILOT_LAST_USER_MESSAGE_CONTEXT_PROMPT_FILE = (
    "latest_user_message_context_prompt.jinja2"
)
COPILOT_LAST_USER_MESSAGE_CONTEXT_PROMPT_FILE_AGENT = (
    "latest_user_message_context_prompt_agent.jinja2"
)
COPILOT_TRAINING_ERROR_HANDLER_PROMPT_FILE = (
    "copilot_training_error_handler_prompt.jinja2"
)
COPILOT_TRAINING_ERROR_HANDLER_PROMPT_FILE_AGENT = (
    "copilot_training_error_handler_prompt_agent.jinja2"
)

# A dot-path for importlib to the Copilot skills (one directory per use case)
COPILOT_SKILLS_DIR = "builder.copilot.skills"

# A dot-path for importlib to the message classifier prompt
MESSAGE_CLASSIFIER_PROMPTS_DIR = "builder.copilot.message_classifier.prompts"
MESSAGE_CLASSIFIER_PROMPT_FILE = "message_classifier_prompt.jinja2"
MESSAGE_CLASSIFIER_ATTACHMENTS_CONTEXT_PROMPT_FILE = (
    "attachments_context_message_classifier_prompt.jinja2"
)


# A dot-path for importlib to the rasa internal messages templates
COPILOT_MESSAGE_TEMPLATES_DIR = "builder.copilot.templated_messages"
RASA_INTERNAL_MESSAGES_TEMPLATES_FILE = "copilot_internal_messages_templates.yml"
COPILOT_HANDLER_RESPONSES_FILE = "copilot_templated_responses.yml"
COPILOT_WELCOME_MESSAGES_FILE = "copilot_welcome_messages.yml"
COPILOT_TEMPLATE_PROMPTS_FILE = "copilot_template_prompts.yml"

# OpenAI roles copilot utilizes - Use literal types to avoid type errors with OpenAI
ROLE_USER: Literal["user"] = "user"
ROLE_SYSTEM: Literal["system"] = "system"
ROLE_ASSISTANT: Literal["assistant"] = "assistant"

# Rasa Copilot role - Added to avoid confusion with the assistant role on the frontend.
ROLE_COPILOT: Literal["copilot"] = "copilot"

# Rasa internal role - Used to indicate that the message is from the Rasa internal
# system components.
ROLE_COPILOT_INTERNAL: Literal["internal_copilot_request"] = "internal_copilot_request"

# Copilot Telemetry
COPILOT_SEGMENT_WRITE_KEY_ENV_VAR = "COPILOT_SEGMENT_WRITE_KEY"

# Welcome message key for prompt-to-bot (not a template enum)
PROMPT_TO_BOT_KEY = "prompt_to_bot"
PROMPT_TO_BOT_TEMPLATE_KEY = "prompt_to_bot_template"

# Default commit message when updating files
DEFAULT_COMMIT_MESSAGE = "Update files"

# File extensions the copilot's file tools surface by default. Covers CALM/legacy
# assistant files (yaml/yml/py/jinja/jinja2) as well as Mantle project files -
# skills/<id>/skill.md, AGENTS.md, and references/*.md|*.txt - which would
# otherwise be silently filtered out of file listing/reading.
COPILOT_DEFAULT_ALLOWED_FILE_EXTENSIONS: List[str] = [
    "yaml",
    "yml",
    "py",
    "jinja",
    "jinja2",
    "md",
    "txt",
]
COPILOT_DEFAULT_ALLOWED_FILE_EXTENSIONS_CSV = ",".join(
    COPILOT_DEFAULT_ALLOWED_FILE_EXTENSIONS
)

# Environment variable name for the project folder path
RASA_PROJECT_FOLDER_ENV_VAR = "RASA_PROJECT_FOLDER"

# Simulation and Evaluation prompt templates
SIMULATED_USER_SYSTEM_PROMPT_FILE = "simulated_user_system_prompt.jinja2"
EVALUATION_CRITERIA_JUDGE_PROMPT_FILE = "evaluation_criteria_judge_prompt.jinja2"
EVALUATION_METRICS_JUDGE_PROMPT_FILE = "evaluation_metrics_judge_prompt.jinja2"

# Documentation-search tool name. Registered natively on Copilot v2 agents
# (pydantic_ai/document_search.py) and backed by local retrieval.
TOOL_SEARCH_RASA_DOCUMENTATION = "search_rasa_documentation"

# Project file tool names. The implementations live in copilot/file_operations.py
# and are registered natively on the agent (pydantic_ai/file_tools.py); the MCP
# server deliberately exposes no generic file tools, since external IDEs bring
# their own.
TOOL_LIST_PROJECT_FILES = "list_project_files"
TOOL_READ_PROJECT_FILES = "read_project_files"
TOOL_GET_PROJECT_FILE = "get_project_file"
TOOL_WRITE_PROJECT_FILE = "write_project_file"
TOOL_UPDATE_MULTIPLE_FILES = "update_multiple_files"

# Branch tool name. Registered natively (pydantic_ai/branch_tool.py), and only
# offered to runs whose client opted into branching.
TOOL_CREATE_BRANCH = "create_branch"

# pydantic-ai's built-in tool for loading a deferred capability by id. Copilot
# skills are deferred capabilities, so this is the tool the model loads them with.
TOOL_LOAD_CAPABILITY = "load_capability"

# Skill reference tool name. Registered natively (pydantic_ai/skills.py), and only
# offered to runs that have Copilot skills.
TOOL_LOAD_SKILL_REFERENCE = "load_skill_reference"
